@dataclass(frozen=True)
class Fragmento:
    texto: str
    doc: str
    titulo: str
    seccion: str

    def para_embedding(self, metadatos=False):
        if not metadatos:
            return self.texto
        encabezado = f"{self.titulo} > {self.seccion}" if self.seccion else self.titulo
        return f"{encabezado}: {self.texto}"

def _secciones(doc):
    """(nombre_de_seccion, texto) por cada bloque entre encabezados; la intro va con seccion ''."""
    bloques, seccion, lineas = [], "", []
    for linea in doc.texto.splitlines():
        if linea.startswith("## "):
            bloques.append((seccion, "\n".join(lineas)))
            seccion, lineas = linea[3:].strip(), []
        elif linea.startswith("# "):
            continue
        else:
            lineas.append(linea)
    bloques.append((seccion, "\n".join(lineas)))
    return [(s, t.strip()) for s, t in bloques if t.strip()]

def _parrafos(texto):
    return [p.strip() for p in re.split(r"\n\s*\n", texto) if p.strip()]


def _oraciones(parrafo):
    partes = []
    for linea in parrafo.splitlines():  # los items de una lista son oraciones sueltas
        partes += re.split(r"(?<=[.!?])\s+(?=[^\sa-z])", linea.strip())
    return [p for p in partes if p]


def _ventanas(texto, palabras, solapamiento):
    spans = [m.span() for m in re.finditer(r"\S+", texto)]
    paso = palabras - solapamiento
    for i in range(0, len(spans), paso):
        grupo = spans[i:i + palabras]
        yield texto[grupo[0][0]:grupo[-1][1]]
        if i + palabras >= len(spans):
            break


def fragmentar(docs, estrategia, palabras=60, solapamiento=15):
    """estrategia: 'seccion' | 'parrafo' | 'oracion' | 'ventana' (usa palabras y solapamiento)."""
    frags = []
    for doc in docs:
        for seccion, texto in _secciones(doc):
            if estrategia == "seccion":
                piezas = [texto]
            elif estrategia == "parrafo":
                piezas = _parrafos(texto)
            elif estrategia == "oracion":
                piezas = [o for p in _parrafos(texto) for o in _oraciones(p)]
            elif estrategia == "ventana":
                piezas = list(_ventanas(texto, palabras, solapamiento))
            else:
                raise ValueError(f"estrategia desconocida: {estrategia}")
            frags += [Fragmento(p, doc.nombre, doc.titulo, seccion) for p in piezas]
    return frags

def _normalizar(m):
    return m / np.linalg.norm(m, axis=1, keepdims=True).clip(min=1e-12)


class BertPromedio:
    """Linea de base obligatoria: BERT sin ajustar para similitud, embedding = promedio de los
    vectores de la ultima capa sobre los tokens reales (se ignora el padding)."""

    def __init__(self, modelo="google-bert/bert-base-multilingual-cased", lote=16):
        from transformers import AutoModel, AutoTokenizer

        self.nombre, self.lote = modelo, lote
        self.tokenizer = AutoTokenizer.from_pretrained(modelo)
        self.modelo = AutoModel.from_pretrained(modelo).eval()

    def _codificar(self, textos):
        import torch

        salidas = []
        with torch.no_grad():
            for i in range(0, len(textos), self.lote):
                enc = self.tokenizer(textos[i:i + self.lote], padding=True, truncation=True,
                                     max_length=512, return_tensors="pt")
                h = self.modelo(**enc).last_hidden_state
                m = enc["attention_mask"].unsqueeze(-1).float()
                salidas.append(((h * m).sum(1) / m.sum(1)).numpy())
        return _normalizar(np.concatenate(salidas))

    codificar_consultas = codificar_pasajes = _codificar

class SentenceTransformerEncoder:
    """Modelos entrenados para embeddings de oraciones (MiniLM, e5, bge-m3). Los e5 piden prefijos."""

    def __init__(self, modelo, prefijo_consulta="", prefijo_pasaje="", lote=16):
        from sentence_transformers import SentenceTransformer

        self.nombre, self.lote = modelo, lote
        self.prefijo_consulta, self.prefijo_pasaje = prefijo_consulta, prefijo_pasaje
        self.modelo = SentenceTransformer(modelo, device="cpu")

    def _codificar(self, textos, prefijo):
        m = self.modelo.encode([prefijo + t for t in textos], batch_size=self.lote,
                               normalize_embeddings=True, show_progress_bar=False)
        return np.asarray(m, dtype=np.float32)

    def codificar_consultas(self, textos):
        return self._codificar(textos, self.prefijo_consulta)

    def codificar_pasajes(self, textos):
        return self._codificar(textos, self.prefijo_pasaje)


def crear_encoder(cfg):
    """cfg: {"tipo": "bert_promedio" | "sentence_transformer", "modelo": ..., "prefijo_consulta": ..., "prefijo_pasaje": ...}"""
    if cfg["tipo"] == "bert_promedio":
        return BertPromedio(cfg["modelo"])
    if cfg["tipo"] == "sentence_transformer":
        return SentenceTransformerEncoder(cfg["modelo"], cfg.get("prefijo_consulta", ""), cfg.get("prefijo_pasaje", ""))
    raise ValueError(f"tipo de encoder desconocido: {cfg['tipo']}")

def _puntuar(self, consulta):
    """[(Fragmento, score)] de todos los fragmentos (o de los candidatos rerankeados), de mayor a menor."""
    q = self.encoder.codificar_consultas([consulta])[0]
    scores = self.matriz @ q
    orden = np.argsort(-scores)
    if self.reranker is None:
        return [(self.fragmentos[i], float(scores[i])) for i in orden]
    cand = orden[:self.candidatos]
    pares = [(consulta, self.fragmentos[i].para_embedding(self.metadatos)) for i in cand]
    re_scores = self.reranker.predict(pares, show_progress_bar=False)
    return sorted(((self.fragmentos[i], float(s)) for i, s in zip(cand, re_scores)), key=lambda x: -x[1])

def puntuar(self, consulta):
    """[(texto, score)] de mayor a menor."""
    return [(f.texto, s) for f, s in self._puntuar(consulta)]

def buscar_fragmentos(self, consulta, **seleccion):
    """Los Fragmento elegidos (texto literal + documento, título y sección). top_k, umbral y margen se
    pueden pisar por llamada; si no, se usan los de la configuración."""
    s = {"top_k": self.top_k, "umbral": self.umbral, "margen": self.margen, **seleccion}
    return seleccionar(self._puntuar(consulta), s["top_k"], s["umbral"], s["margen"])

def buscar(self, consulta):
    return [f.texto for f in self.buscar_fragmentos(consulta)]

class Recuperador:
    def __init__(self, docs, encoder, estrategia="seccion", palabras=60, solapamiento=15, metadatos=False,
                 top_k=3, umbral=None, margen=None, reranker=None, candidatos=20):
        self.encoder, self.metadatos = encoder, metadatos
        self.top_k, self.umbral, self.margen = top_k, umbral, margen
        self.reranker, self.candidatos = reranker, candidatos
        self.fragmentos = fragmentar(docs, estrategia, palabras=palabras, solapamiento=solapamiento)
        self.matriz = self._embeddings([f.para_embedding(metadatos) for f in self.fragmentos])

    def _embeddings(self, textos):
        nombre = getattr(self.encoder, "nombre", None)
        if nombre is None:
            return self.encoder.codificar_pasajes(textos)
        prefijo = getattr(self.encoder, "prefijo_pasaje", "")
        clave = hashlib.sha1(json.dumps([nombre, prefijo, textos]).encode()).hexdigest()[:16]
        ruta = CACHE / f"{clave}.npy"
        if ruta.exists():
            return np.load(ruta)
        m = self.encoder.codificar_pasajes(textos)
        CACHE.mkdir(parents=True, exist_ok=True)
        np.save(ruta, m)
        return m

    @classmethod
    def desde_config(cls, cfg):
        """cfg: dict o ruta a un JSON como hospital/rag/config.json."""
        if not isinstance(cfg, dict):
            cfg = json.loads(Path(cfg).read_text(encoding="utf-8"))
        chunk = cfg.get("chunking", {})
        reranker = None
        if cfg.get("reranker"):
            from sentence_transformers import CrossEncoder
            reranker = CrossEncoder(cfg["reranker"]["modelo"], device="cpu")
        return cls(cargar_corpus(RAIZ / cfg.get("corpus", "datos/corpus")), crear_encoder(cfg["encoder"]),
                   estrategia=chunk.get("estrategia", "seccion"), palabras=chunk.get("palabras", 60),
                   solapamiento=chunk.get("solapamiento", 15), metadatos=cfg.get("metadatos", False),
                   top_k=cfg.get("top_k", 3), umbral=cfg.get("umbral"), margen=cfg.get("margen"),
                   reranker=reranker, candidatos=(cfg.get("reranker") or {}).get("candidatos", 20))


@lru_cache(maxsize=1)
def obtener_recuperador(ruta=str(CONFIG)):
    """Instancia unica con la configuracion ganadora (la usan recuperar.py, el agente y el servidor MCP)."""
    return Recuperador.desde_config(ruta)

