import json

from hospital.rag.recuperador import CONFIG, obtener_recuperador

SEPARADOR = "\n\n---\n\n"


def seleccion_agente():
    return json.loads(CONFIG.read_text(encoding="utf-8")).get("agente", {})


def buscar_documentos(consulta):
    """Fragmentos elegidos, cada uno con su fuente '[Documento > Sección]' arriba del texto literal."""
    seleccion = seleccion_agente()
    # En consultas sobre documentacion o que llevar, la seccion especifica puede
    # quedar tercera cuando la pregunta tambien menciona el tipo de turno.
    # La configuracion de la Parte 1 permanece sin cambios.
    consulta_normalizada = consulta.casefold()
    if "llevar" in consulta_normalizada or "document" in consulta_normalizada:
        seleccion = {**seleccion, "top_k": max(seleccion.get("top_k", 2), 3), "margen": None}
    bloques = []
    for f in obtener_recuperador().buscar_fragmentos(consulta, **seleccion):
        fuente = f"{f.titulo} > {f.seccion}" if f.seccion else f.titulo
        bloques.append(f"[{fuente}]\n{f.texto}")
    return SEPARADOR.join(bloques) or "No se encontraron documentos para esa consulta."

"""Cliente de la API del hospital (api/servidor.py). Sin LangChain: lo usan las tools de la parte 2 y el
servidor MCP de la parte 3.

Cada funcion devuelve el cuerpo JSON como texto, tambien cuando la API responde con error (404 con la lista
de opciones validas), para que el modelo pueda corregirse y reintentar.
"""
import json
import os
import urllib.error
import urllib.parse
import urllib.request


def _get(ruta, **params):
    base = os.environ.get("HOSPITAL_API", "http://localhost:8765")
    url = f"{base}{ruta}"
    if params:
        url += "?" + urllib.parse.urlencode(params)
    try:
        with urllib.request.urlopen(url, timeout=10) as r:
            return r.read().decode("utf-8")
    except urllib.error.HTTPError as e:  # 400/404 traen JSON con "error" y "opciones"
        return e.read().decode("utf-8")
    except OSError as e:
        return json.dumps({"error": f"la API del hospital no responde en {base}: {e}"}, ensure_ascii=False)


def camas(sector):
    return _get("/camas", sector=sector)


def guardia(especialidad):
    return _get("/guardia", especialidad=especialidad)


def turnos(especialidad):
    return _get("/turnos", especialidad=especialidad)


def farmacia(medicamento):
    return _get("/farmacia", medicamento=medicamento)


def espera():
    return _get("/espera")

async def _ejecutar(por_nombre, llamada):
    tool = por_nombre.get(llamada["name"])
    if tool is None:
        return ToolMessage(f"Error: la herramienta '{llamada['name']}' no existe. Herramientas disponibles: "
                           f"{', '.join(sorted(por_nombre))}.", tool_call_id=llamada["id"], name=llamada["name"])
    try:
        return await tool.ainvoke({**llamada, "type": "tool_call"})
    except Exception as e:  # el error vuelve al modelo como texto para que pueda corregirse
        return ToolMessage(f"Error al ejecutar {llamada['name']}: {e}", tool_call_id=llamada["id"], name=llamada["name"])


async def responder(llm, tools, pregunta):
    """Devuelve todos los mensajes de la conversación: sistema, pregunta, AIMessage y ToolMessage."""
    llm_con_tools = llm.bind_tools(tools)
    por_nombre = {t.name: t for t in tools}
    mensajes = [SystemMessage(PROMPT), HumanMessage(pregunta)]
    for _ in range(MAX_PASOS):
        ai = await llm_con_tools.ainvoke(mensajes)
        mensajes.append(ai)
        if not ai.tool_calls:
            break
        for llamada in ai.tool_calls:
            mensajes.append(await _ejecutar(por_nombre, llamada))
    return mensajes

def _usage(ai):
    u = ai.usage_metadata or {}
    uso = (ai.response_metadata or {}).get("token_usage") or {}
    entrada, salida = u.get("input_tokens", 0), u.get("output_tokens", 0)
    costo = uso.get("cost")
    return {
        "tokens_entrada": entrada,
        "tokens_cache": (u.get("input_token_details") or {}).get("cache_read", 0),
        "tokens_salida": salida,
        "tokens_razonamiento": (u.get("output_token_details") or {}).get("reasoning", 0),
        "costo": costo if costo is not None else entrada * PRECIO_ENTRADA + salida * PRECIO_SALIDA,
        "costo_estimado": costo is None,
        "id": (ai.response_metadata or {}).get("id"),
    }


def resumir(mensajes):
    ais = [m for m in mensajes if isinstance(m, AIMessage)]
    herramientas = []
    for m in ais:
        for c in m.tool_calls:
            if c["name"] not in herramientas:
                herramientas.append(c["name"])
    llamadas = [_usage(m) for m in ais]
    respuesta = next((texto(m.content).strip() for m in reversed(ais) if texto(m.content).strip()), "")
    return {
        "respuesta": respuesta,
        "contextos": [texto(m.content) for m in mensajes if isinstance(m, ToolMessage)],
        "herramientas": herramientas,
        "llamadas_modelo": llamadas,
        "tokens_entrada": sum(l["tokens_entrada"] for l in llamadas),
        "tokens_salida": sum(l["tokens_salida"] for l in llamadas),
        "costo": sum(l["costo"] for l in llamadas),
    }

